insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$nova-monte-verde$q$, $q$https://amm.diariomunicipal.org/publicacao/27741/ (Lei 741/2015); https://amm.diariomunicipal.org/publicacao/91098/ (Lei 778/2015)$q$, $q$Atos oficiais municipais: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria derivada do OpenStreetMap: ODbL 1.0 (© colaboradores do OpenStreetMap), base derivada separada do OSM.$q$, 16, $q$Lei Municipal 741, de 06/05/2015 (AMM-MT 08/05/2015) e Lei 778/2015 (Código de Posturas), art. 254, §2º, que repete o critério. Nenhuma alteração ou revogação posterior encontrada. O Código de Posturas citava art. 250 §2º na pesquisa; a verificação corrigiu para art. 254 §2º. A Praça da Bíblia não está mapeada por nome no OSM e o 'ao redor' não tem raio no ato: o entorno fica fora da geometria (a praça fica na própria Av. Mato Grosso, que está inteira na regra).$q$);
